{
  "plans": [
    {
      "name": "lgbm_recall_tuned",
      "steps": [
        {
          "kind": "imputer",
          "action": "synthesize",
          "synth_spec": {
            "name": "TotalChargesCleaner",
            "kind": "imputer",
            "purpose": "处理数值列中包含的空白字符串及异常，确保total_charges能转换为浮点数并填补缺失值",
            "inputs": "原始数据框",
            "outputs": "处理后的数据框",
            "reference": "TotalChargesCleaner@1"
          },
          "evidence_ids": [
            "Operator:TotalChargesCleaner@1"
          ]
        },
        {
          "kind": "imputer",
          "action": "reuse",
          "operator_ref": "MissingValueImputer@1",
          "evidence_ids": [
            "Operator:MissingValueImputer@1"
          ]
        },
        {
          "kind": "feature",
          "action": "synthesize",
          "synth_spec": {
            "name": "IdColumnDropper",
            "kind": "feature",
            "purpose": "删除客户ID等标识列，防止维度爆炸并避免过拟合",
            "inputs": "含标识列的数据框",
            "outputs": "已剔除标识列的数据框",
            "reference": "IdColumnDropper@1"
          },
          "evidence_ids": [
            "Operator:IdColumnDropper@1"
          ]
        },
        {
          "kind": "encoder",
          "action": "reuse",
          "operator_ref": "OneHotCategoricalEncoder@1",
          "evidence_ids": [
            "Operator:OneHotCategoricalEncoder@1"
          ]
        },
        {
          "kind": "model",
          "action": "reuse",
          "operator_ref": "LightGBMModel@1",
          "params": {
            "n_estimators": 600,
            "learning_rate": 0.03,
            "num_leaves": 63,
            "class_weight": {
              "0": 1,
              "1": 3
            },
            "random_state": 42
          },
          "rationale": "基于父方案，加大少数类权重并调整树参数以提升召回率，满足Lesson:f2c1398b。",
          "evidence_ids": [
            "Operator:LightGBMModel@1",
            "Lesson:f2c1398b"
          ]
        }
      ],
      "rationale": "针对父方案召回不足的问题，进一步调大正类权重并增加模型复杂度（增大num_leaves和n_estimators），重点优化召回率。"
    },
    {
      "name": "lgbm_with_feature_engineering",
      "steps": [
        {
          "kind": "imputer",
          "action": "synthesize",
          "synth_spec": {
            "name": "TotalChargesCleaner",
            "kind": "imputer",
            "purpose": "处理数值列中包含的空白字符串",
            "inputs": "原始数据框",
            "outputs": "处理后的数据框",
            "reference": "TotalChargesCleaner@1"
          },
          "evidence_ids": [
            "Operator:TotalChargesCleaner@1"
          ]
        },
        {
          "kind": "feature",
          "action": "synthesize",
          "synth_spec": {
            "name": "ChargeRatioFeatureGenerator",
            "kind": "feature",
            "purpose": "构造资费变动特征",
            "inputs": "包含tenure, monthly, total的列",
            "outputs": "新增比值特征的数据框",
            "reference": "ChargeRatioFeatureGenerator@1"
          },
          "evidence_ids": [
            "Operator:ChargeRatioFeatureGenerator@1"
          ]
        },
        {
          "kind": "encoder",
          "action": "reuse",
          "operator_ref": "OneHotCategoricalEncoder@1"
        },
        {
          "kind": "model",
          "action": "reuse",
          "operator_ref": "LightGBMModel@1",
          "params": {
            "n_estimators": 500,
            "class_weight": "balanced",
            "random_state": 42
          },
          "rationale": "引入业务特征以增强模型对流失倾向的刻画，配合balanced权重。",
          "evidence_ids": [
            "Operator:LightGBMModel@1",
            "Operator:ChargeRatioFeatureGenerator@1"
          ]
        }
      ],
      "rationale": "引入领域相关特征（资费比率）来增强模型判别力，从而间接优化召回率。"
    },
    {
      "name": "rf_recall_optimized",
      "steps": [
        {
          "kind": "imputer",
          "action": "reuse",
          "operator_ref": "MissingValueImputer@1"
        },
        {
          "kind": "encoder",
          "action": "reuse",
          "operator_ref": "OneHotCategoricalEncoder@1"
        },
        {
          "kind": "model",
          "action": "reuse",
          "operator_ref": "RandomForestModel@1",
          "params": {
            "n_estimators": 500,
            "max_depth": 12,
            "class_weight": "balanced_subsample",
            "random_state": 42
          },
          "rationale": "改用随机森林，通过balanced_subsample增强少数类捕捉，结合Lesson:57718714进行深度限制。",
          "evidence_ids": [
            "Operator:RandomForestModel@1",
            "Lesson:57718714"
          ]
        }
      ],
      "rationale": "替换模型为随机森林，利用其处理混合特征的优势，并通过设置balanced_subsample强制对少数类加权。"
    },
    {
      "name": "logreg_interpretable_tuned",
      "steps": [
        {
          "kind": "imputer",
          "action": "reuse",
          "operator_ref": "MissingValueImputer@1"
        },
        {
          "kind": "encoder",
          "action": "reuse",
          "operator_ref": "OneHotCategoricalEncoder@1"
        },
        {
          "kind": "scaler",
          "action": "reuse",
          "operator_ref": "StandardFeatureScaler@1"
        },
        {
          "kind": "model",
          "action": "reuse",
          "operator_ref": "LogisticRegressionModel@1",
          "params": {
            "C": 0.5,
            "class_weight": {
              "0": 1,
              "1": 4
            },
            "random_state": 42
          },
          "rationale": "逻辑回归方案，满足可解释性要求，通过手动加大正类权重来实现召回率目标。",
          "evidence_ids": [
            "Operator:LogisticRegressionModel@1",
            "Lesson:74e2da10"
          ]
        }
      ],
      "rationale": "尝试可解释模型，通过更强的逻辑回归权重偏置(class_weight dict)平衡类别权重，争取达到recall阈值。"
    }
  ]
}

